export interface ConstructionCatalogResource{name:string;amount:number}
export interface ConstructionCatalogEntry{
  id:ConstructionId
  name:string
  description:string
  branchId:ConstructionBranchId
  branchLabel:string
  parentId:ConstructionId|null
  blueprintClass:ConstructionBlueprintClass
  apCost:number
  maxHp:number
  defense:number
  breakable:boolean
  temporary:boolean
  hasUpgrade:boolean
  resources:readonly ConstructionCatalogResource[]
  implementation:ConstructionImplementationStatus
  wipReason:string|null
}

